<?php require __DIR__.'/../app/bootstrap.php'; require_login(); require_permission('documents.upload'); verify_csrf();
try{$type=$_POST['document_type']??'Lainnya';$folder=$type==='Foto Kerusakan'?'damage':($type==='Quotation'?'quotations':($type==='Purchase Order'?'purchase_orders':'documents'));$f=upload_file($_FILES['document'],$folder);$stmt=$pdo->prepare('INSERT INTO unit_documents(unit_id,document_type,original_name,stored_name,file_path,mime_type,file_size,notes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?)');$stmt->execute([($_POST['unit_id']??'')?:null,$type,$f['original_name'],$f['stored_name'],$f['file_path'],$f['mime_type'],$f['file_size'],trim($_POST['notes']??''),current_user()['id']]);audit($pdo,'UPLOAD','document',(int)$pdo->lastInsertId(),'Upload '.$type);flash('success','Dokumen berhasil diunggah.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('../'.page_url('documents'));
